#include <string>
#include <vector>
#include <cstring>

class Solution {
public:
    int countKReducibleNumbers(std::string s, int k) {
        const int MOD = 1000000007;
        int n = s.size();

        std::vector<int> steps(n + 1, 0);
        for (int i = 2; i <= n; ++i) {
            steps[i] = steps[__builtin_popcount(i)] + 1;
        }

        std::vector<bool> valid(n + 1, false);
        for (int i = 1; i <= n; ++i) {
            if (steps[i] <= k - 1) valid[i] = true;
        }

        int memo[805][805][2];
        std::memset(memo, -1, sizeof(memo));

        auto dp = [&](auto& self, int idx, int count, bool tight) -> int {
            if (idx == n) {
                return (!tight && valid[count]) ? 1 : 0;
            }
            if (memo[idx][count][tight] != -1) return memo[idx][count][tight];

            int limit = tight ? (s[idx] - '0') : 1;
            long long res = 0;
            for (int digit = 0; digit <= limit; ++digit) {
                res = (res + self(self, idx + 1, count + digit, tight && (digit == limit))) % MOD;
            }
            return memo[idx][count][tight] = res;
        };

        return dp(dp, 0, 0, true);
    }
};

import java.util.*;

class Solution {
    public int countKReducibleNumbers(String s, int k) {
        int MOD = 1_000_000_007;
        int n = s.length();

        int[] steps = new int[n + 1];
        for (int i = 2; i <= n; i++) {
            steps[i] = steps[Integer.bitCount(i)] + 1;
        }

        boolean[] valid = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            if (steps[i] <= k - 1) valid[i] = true;
        }

        Integer[][][] memo = new Integer[n + 1][n + 1][2];
        return solve(0, 0, 1, s, valid, memo, MOD);
    }

    private int solve(int idx, int count, int tight, String s, boolean[] valid, Integer[][][] memo, int MOD) {
        if (idx == s.length()) {
            return (tight == 0 && valid[count]) ? 1 : 0;
        }
        if (memo[idx][count][tight] != null) return memo[idx][count][tight];

        int limit = (tight == 1) ? (s.charAt(idx) - '0') : 1;
        long res = 0;
        for (int digit = 0; digit <= limit; digit++) {
            int nextTight = (tight == 1 && digit == limit) ? 1 : 0;
            res = (res + solve(idx + 1, count + digit, nextTight, s, valid, memo, MOD)) % MOD;
        }
        return memo[idx][count][tight] = (int) res;
    }
}

var countKReducibleNumbers = function(s, k) {
    const MOD = 1000000007;
    const n = s.length;

    const steps = new Array(n + 1).fill(0);
    for (let i = 2; i <= n; i++) {
        let pop = 0, tmp = i;
        while (tmp > 0) {
            pop += (tmp & 1);
            tmp >>= 1;
        }
        steps[i] = steps[pop] + 1;
    }

    const valid = new Array(n + 1).fill(false);
    for (let i = 1; i <= n; i++) {
        if (steps[i] <= k - 1) valid[i] = true;
    }

    const memo = new Map();
    function dp(idx, count, tight) {
        if (idx === n) {
            return (!tight && valid[count]) ? 1 : 0;
        }
        const key = (idx << 11) | (count << 1) | (tight ? 1 : 0);
        if (memo.has(key)) return memo.get(key);

        const limit = tight ? Number(s[idx]) : 1;
        let res = 0;
        for (let digit = 0; digit <= limit; digit++) {
            res = (res + dp(idx + 1, count + digit, tight && (digit === limit))) % MOD;
        }
        memo.set(key, res);
        return res;
    }

    return dp(0, 0, true);
};
